solution_files.source/unit_09.py:
def mask_email(address):
    value = address.strip()
    if value.count('@') != 1:
        raise ValueError('invalid email')
    local, domain = value.split('@')
    if not local or not domain:
        raise ValueError('invalid email')
    return local[0] + '***@' + domain

